package checkout_test

// UNIT TESTS for saving orders (rules §6), and the project's showcase of TEST DOUBLES.
//
// A test double stands in for a real dependency:
//   - a FAKE is a simple working version – InMemoryOrderRepository is one,
//   - a STUB gives canned answers – FixedClock always says the same time,
//   - a MOCK records how it was called and checks it – the gomock mocks in internal/mocks
//     (generated by mockgen from the interfaces in orders.go) let us prove that Save was
//     called exactly once, with exactly this receipt, or never at all.
//
// The last test uses goroutines and is meant to be run with `go test -race`.

import (
	"errors"
	"fmt"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/google/go-cmp/cmp"
	"go.uber.org/mock/gomock"

	"github.com/AJayClauGermany/the-most-well-tested-checkout-system/go/checkout"
	"github.com/AJayClauGermany/the-most-well-tested-checkout-system/go/internal/fixtures"
	"github.com/AJayClauGermany/the-most-well-tested-checkout-system/go/internal/mocks"
)

// --- Clocks and timestamps --------------------------------------------------

func TestFormatTimestamp(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name string
		time time.Time
		want string
	}{
		{
			name: "writes UTC with whole seconds and a trailing Z",
			time: time.Date(2026, 1, 15, 10, 30, 0, 0, time.UTC),
			want: "2026-01-15T10:30:00Z",
		},
		{
			name: "drops fractions of a second instead of rounding them",
			time: time.Date(2026, 1, 15, 10, 30, 0, 999_000_000, time.UTC),
			want: "2026-01-15T10:30:00Z",
		},
		{
			name: "converts other time zones to UTC",
			time: time.Date(2026, 1, 15, 12, 30, 0, 0, time.FixedZone("CEST", 2*60*60)),
			want: "2026-01-15T10:30:00Z",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := checkout.FormatTimestamp(tt.time); got != tt.want {
				t.Errorf("FormatTimestamp(%v) = %q, want %q", tt.time, got, tt.want)
			}
		})
	}
}

func TestFixedClockAlwaysAnswersTheSameTime(t *testing.T) {
	t.Parallel()
	clock := checkout.FixedClock(fixtures.FixedTime)

	first := clock.Now()
	time.Sleep(time.Millisecond) // real time moves on …
	second := clock.Now()

	// … but the fixed clock does not.
	if first != fixtures.FixedTime || second != fixtures.FixedTime {
		t.Errorf("FixedClock().Now() = %v then %v, want %v every time", first, second, fixtures.FixedTime)
	}
}

func TestSystemClockReadsTheRealTime(t *testing.T) {
	t.Parallel()
	before := time.Now()

	now := checkout.SystemClock().Now()

	if now.Before(before) || now.After(time.Now()) {
		t.Errorf("SystemClock().Now() = %v, want a moment between %v and now", now, before)
	}
}

func TestClockFuncTurnsAFunctionIntoAClock(t *testing.T) {
	t.Parallel()
	calls := 0
	clock := checkout.ClockFunc(func() time.Time { calls++; return fixtures.FixedTime })

	got := clock.Now()

	if got != fixtures.FixedTime || calls != 1 {
		t.Errorf("Now() = %v after %d call(s), want %v after 1", got, calls, fixtures.FixedTime)
	}
}

// --- Order ids ---------------------------------------------------------------

func TestOrderIDAndOrderNumberAreInverses(t *testing.T) {
	t.Parallel()
	tests := []struct {
		n  int
		id string
	}{
		{n: 1, id: "ORDER-1"},
		{n: 2, id: "ORDER-2"},
		{n: 10, id: "ORDER-10"},
		{n: 1234, id: "ORDER-1234"},
	}

	for _, tt := range tests {
		t.Run(tt.id, func(t *testing.T) {
			t.Parallel()
			if got := checkout.OrderID(tt.n); got != tt.id {
				t.Errorf("OrderID(%d) = %q, want %q", tt.n, got, tt.id)
			}
			n, ok := checkout.OrderNumber(tt.id)
			if !ok || n != tt.n {
				t.Errorf("OrderNumber(%q) = %d, %v; want %d, true", tt.id, n, ok, tt.n)
			}
		})
	}
}

func TestOrderNumberDoesNotRecogniseThingsThatAreNotOrderIDs(t *testing.T) {
	t.Parallel()
	notIDs := []string{
		"", "ORDER-", "ORDER-0", "ORDER-01", "ORDER--1", "ORDER-1.5", "ORDER-1 ", " ORDER-1",
		"MYORDER-1", "ORDER-1x", "order-1", "ORDER-x", "1", "ORDER_1",
		"ORDER-99999999999999999999", // too big for an int
	}

	for _, id := range notIDs {
		t.Run(fmt.Sprintf("%q", id), func(t *testing.T) {
			t.Parallel()
			if n, ok := checkout.OrderNumber(id); ok {
				t.Errorf("OrderNumber(%q) = %d, true; want not an order id", id, n)
			}
		})
	}
}

// --- The hand-written fake ----------------------------------------------------

func TestInMemoryRepositoryStartsEmpty(t *testing.T) {
	t.Parallel()
	repository := checkout.NewInMemoryOrderRepository(fixtures.FixedClock())

	if repository.Count() != 0 {
		t.Errorf("Count() = %d, want 0", repository.Count())
	}
	order, err := repository.Find("ORDER-1")
	if err != nil || order != nil {
		t.Errorf("Find(ORDER-1) = %v, %v; want nil, nil (not found)", order, err)
	}
}

func TestInMemoryRepositoryNumbersOrdersInTheOrderTheyAreSaved(t *testing.T) {
	t.Parallel()
	repository := checkout.NewInMemoryOrderRepository(fixtures.FixedClock())

	var ids []string
	for range 3 {
		id, err := repository.Save(fixtures.OneAppleReceipt())
		if err != nil {
			t.Fatalf("Save() returned an error: %v", err)
		}
		ids = append(ids, id)
	}

	if diff := cmp.Diff([]string{"ORDER-1", "ORDER-2", "ORDER-3"}, ids); diff != "" {
		t.Errorf("ids mismatch (-want +got):\n%s", diff)
	}
	if repository.Count() != 3 {
		t.Errorf("Count() = %d, want 3", repository.Count())
	}
}

func TestInMemoryRepositoryFindsASavedOrderWithItsReceiptAndTheClocksTime(t *testing.T) {
	t.Parallel()
	repository := checkout.NewInMemoryOrderRepository(fixtures.FixedClock())
	id, _ := repository.Save(fixtures.OneAppleReceipt())

	order, err := repository.Find(id)

	if err != nil {
		t.Fatalf("Find() returned an error: %v", err)
	}
	want := &checkout.Order{ID: "ORDER-1", CreatedAt: fixtures.FixedTimestamp, Receipt: fixtures.OneAppleReceipt()}
	if diff := cmp.Diff(want, order); diff != "" {
		t.Errorf("Find() mismatch (-want +got):\n%s", diff)
	}
}

func TestInMemoryRepositoryAsksTheClockOncePerSave(t *testing.T) {
	t.Parallel()
	// A MOCK clock: it answers like the stub, and gomock checks it was asked exactly twice.
	ctrl := gomock.NewController(t)
	clock := mocks.NewMockClock(ctrl)
	clock.EXPECT().Now().Return(fixtures.FixedTime).Times(2)
	repository := checkout.NewInMemoryOrderRepository(clock)

	repository.Save(fixtures.OneAppleReceipt())
	repository.Save(fixtures.OneAppleReceipt())
	// The controller checks the call count when the test ends.
}

func TestInMemoryRepositoryKeepsACopyOfTheReceipt(t *testing.T) {
	t.Parallel()
	repository := checkout.NewInMemoryOrderRepository(fixtures.FixedClock())
	receipt := fixtures.OneAppleReceipt()
	id, _ := repository.Save(receipt)

	// Changing the original later must not change the saved order …
	receipt.Total = 1
	receipt.Lines[0].Quantity = 42
	// … and neither must changing an order we were given back.
	found, _ := repository.Find(id)
	found.Receipt.Lines[0].Quantity = 7

	again, _ := repository.Find(id)
	if diff := cmp.Diff(fixtures.OneAppleReceipt(), again.Receipt); diff != "" {
		t.Errorf("the saved receipt changed (-want +got):\n%s", diff)
	}
}

func TestInMemoryRepositoryAnswersNotFoundForIDsThatWereNeverHandedOut(t *testing.T) {
	t.Parallel()
	repository := checkout.NewInMemoryOrderRepository(fixtures.FixedClock())
	repository.Save(fixtures.OneAppleReceipt())

	for _, id := range []string{"ORDER-2", "ORDER-0", "ORDER-99", "order-1", ""} {
		order, err := repository.Find(id)
		if err != nil || order != nil {
			t.Errorf("Find(%q) = %v, %v; want nil, nil (not found)", id, order, err)
		}
	}
}

func TestInMemoryRepositoryUsesTheRealClockWhenNoneIsGiven(t *testing.T) {
	t.Parallel()
	repository := checkout.NewInMemoryOrderRepository(nil)
	before := time.Now().UTC().Truncate(time.Second)

	id, _ := repository.Save(fixtures.OneAppleReceipt())

	order, _ := repository.Find(id)
	createdAt, err := time.Parse(time.RFC3339, order.CreatedAt)
	if err != nil {
		t.Fatalf("created_at %q is not a timestamp: %v", order.CreatedAt, err)
	}
	if !strings.HasSuffix(order.CreatedAt, "Z") {
		t.Errorf("created_at = %q, want a UTC timestamp ending in Z", order.CreatedAt)
	}
	if createdAt.Before(before) || createdAt.After(time.Now()) {
		t.Errorf("created_at = %v, want a moment between %v and now", createdAt, before)
	}
}

// --- PlaceOrder = checkout + save -----------------------------------------------

func TestPlaceOrderChecksOutAndSavesTheReceipt(t *testing.T) {
	t.Parallel()
	repository := checkout.NewInMemoryOrderRepository(fixtures.FixedClock())

	placed, err := checkout.PlaceOrder(items(item("APPLE", 1)), fixtures.TinyCatalog, repository)

	if err != nil {
		t.Fatalf("PlaceOrder() returned an error: %v", err)
	}
	if placed.OrderID != "ORDER-1" {
		t.Errorf("OrderID = %q, want ORDER-1", placed.OrderID)
	}
	if diff := cmp.Diff(fixtures.OneAppleReceipt(), placed.Receipt); diff != "" {
		t.Errorf("Receipt mismatch (-want +got):\n%s", diff)
	}
	saved, _ := repository.Find("ORDER-1")
	if diff := cmp.Diff(placed.Receipt, saved.Receipt); diff != "" {
		t.Errorf("the saved receipt is not the one returned (-returned +saved):\n%s", diff)
	}
}

func TestPlaceOrderSavesExactlyWhatItReturnsCheckedWithAMock(t *testing.T) {
	t.Parallel()
	// A MOCK repository, generated by mockgen. EXPECT() says what must happen; gomock fails
	// the test on any call that was not expected, and on expected calls that never came.
	ctrl := gomock.NewController(t)
	repository := mocks.NewMockOrderRepository(ctrl)
	wantReceipt, _ := checkout.Checkout(items(item("TV", 1)), fixtures.TinyCatalog)
	repository.EXPECT().Save(wantReceipt).Return("ORDER-7", nil).Times(1)
	// No EXPECT() for Find: calling it would fail the test.

	placed, err := checkout.PlaceOrder(items(item("TV", 1)), fixtures.TinyCatalog, repository)

	if err != nil {
		t.Fatalf("PlaceOrder() returned an error: %v", err)
	}
	if placed.OrderID != "ORDER-7" { // the id comes from the repository, not from PlaceOrder
		t.Errorf("OrderID = %q, want ORDER-7", placed.OrderID)
	}
}

func TestPlaceOrderSavesNothingWhenCheckoutFails(t *testing.T) {
	t.Parallel()
	// Property P14, as an example: the mock must never see a Save call.
	ctrl := gomock.NewController(t)
	repository := mocks.NewMockOrderRepository(ctrl)
	repository.EXPECT().Save(gomock.Any()).Times(0)

	_, err := checkout.PlaceOrder(items(), fixtures.TinyCatalog, repository)
	assertErrorCode(t, err, checkout.CodeEmptyBasket)

	_, err = checkout.PlaceOrder(items(item("BANANA", 1)), fixtures.TinyCatalog, repository)
	assertErrorCode(t, err, checkout.CodeUnknownProduct)
}

func TestPlaceOrderLeavesTheFakeRepositoryEmptyAfterAFailedCheckout(t *testing.T) {
	t.Parallel()
	repository := checkout.NewInMemoryOrderRepository(fixtures.FixedClock())

	_, err := checkout.PlaceOrder(items(item("APPLE", 0)), fixtures.TinyCatalog, repository)

	assertErrorCode(t, err, checkout.CodeInvalidQuantity)
	if repository.Count() != 0 {
		t.Errorf("Count() = %d, want 0", repository.Count())
	}
}

func TestPlaceOrderPassesOnAFailureToSave(t *testing.T) {
	t.Parallel()
	ctrl := gomock.NewController(t)
	repository := mocks.NewMockOrderRepository(ctrl)
	diskFull := errors.New("disk full")
	repository.EXPECT().Save(gomock.Any()).Return("", diskFull)

	_, err := checkout.PlaceOrder(items(item("APPLE", 1)), fixtures.TinyCatalog, repository)

	if !errors.Is(err, diskFull) {
		t.Errorf("err = %v, want it to wrap %v", err, diskFull)
	}
	if err == nil || !strings.Contains(err.Error(), "saving the order") {
		t.Errorf("err = %v, want it to say what was being done", err)
	}
}

// --- Concurrency: run with `go test -race` ------------------------------------------

func TestInMemoryRepositoryIsSafeToUseFromManyGoroutines(t *testing.T) {
	t.Parallel()
	// A CONCURRENCY test: 50 goroutines save at the same time. Without the mutex in the
	// repository the race detector (`go test -race`) reports a data race here, and the ids
	// would not come out as exactly ORDER-1 … ORDER-50.
	repository := checkout.NewInMemoryOrderRepository(fixtures.FixedClock())
	const savers = 50

	var wg sync.WaitGroup
	ids := make(chan string, savers)
	for range savers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			id, err := repository.Save(fixtures.OneAppleReceipt())
			if err != nil {
				t.Errorf("Save() returned an error: %v", err)
			}
			ids <- id
			repository.Find(id) // readers and writers at the same time
		}()
	}
	wg.Wait()
	close(ids)

	seen := map[string]bool{}
	for id := range ids {
		seen[id] = true
	}
	for n := 1; n <= savers; n++ {
		if !seen[checkout.OrderID(n)] {
			t.Errorf("id %s was never handed out", checkout.OrderID(n))
		}
	}
	if repository.Count() != savers {
		t.Errorf("Count() = %d, want %d", repository.Count(), savers)
	}
}
